def prosti_brojevi(n):
    rezultat = []
    for broj in range(2, n + 1):
        prost = True
        for djelilac in range(2, int(broj ** 0.5) + 1):
            if broj % djelilac == 0:
                prost = False
                break
        if prost:
            rezultat.append(broj)
    return rezultat

